import test from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const { createCache } = await import(pathToFileURL(path.join(process.env.RDSH_FIXTURE_ROOT, 'src/cache.mjs')).href);
test('all falsey values are stored', () => {
  const c=createCache({capacity:5,ttl:10,now:()=>0});
  for(const [i,v] of [false,0,'',null,undefined].entries()) c.set(i,v);
  for(const [i,v] of [false,0,'',null,undefined].entries()){assert.equal(c.has(i),true);assert.equal(c.get(i),v);}
});
test('exact deadline expires',()=>{let t=10;const c=createCache({capacity:2,ttl:5,now:()=>t});c.set('x',1);t=15;assert.equal(c.get('x'),undefined);assert.equal(c.has('x'),false);});
test('zero TTL has no live entries',()=>{const c=createCache({capacity:2,ttl:0,now:()=>42});c.set('x',1);assert.equal(c.has('x'),false);assert.equal(c.size(),0);});
test('get refreshes recency but has does not',()=>{const c=createCache({capacity:2,ttl:20,now:()=>0});c.set('a',1);c.set('b',2);c.get('a');c.has('b');c.set('c',3);assert.equal(c.has('a'),true);assert.equal(c.has('b'),false);});
test('update preserves other live entries and refreshes recency',()=>{const c=createCache({capacity:2,ttl:20,now:()=>0});c.set('a',1);c.set('b',2);c.set('b',22);assert.equal(c.size(),2);assert.equal(c.get('a'),1);assert.equal(c.get('b'),22);});
test('size prunes and reads do not extend TTL',()=>{let t=0;const c=createCache({capacity:3,ttl:5,now:()=>t});c.set('a',1);t=2;c.set('b',2);c.get('a');t=6;assert.equal(c.size(),1);assert.equal(c.get('a'),undefined);assert.equal(c.get('b'),2);});
test('set renews deadline for existing key',()=>{let t=0;const c=createCache({capacity:2,ttl:5,now:()=>t});c.set('a',1);t=4;c.set('a',2);t=6;assert.equal(c.get('a'),2);t=9;assert.equal(c.has('a'),false);});
test('invalid capacity and TTL rejected',()=>{for(const capacity of [0,-1,1.5,NaN,Infinity])assert.throws(()=>createCache({capacity}),RangeError);for(const ttl of [-1,NaN,Infinity])assert.throws(()=>createCache({ttl}),RangeError);});

